<?php
if(!defined('ABSPATH')){exit;}
final class NVConsult_Core_Retention{
 public static function init():void{add_action('admin_init',[self::class,'settings']);add_action('admin_menu',[self::class,'menu'],22);}
 public static function settings():void{register_setting('nvconsult_retention','nvconsult_retention_months',['type'=>'integer','sanitize_callback'=>static fn($v)=>max(1,min(120,absint($v))),'default'=>24]);}
 public static function menu():void{if(current_user_can('manage_options'))add_submenu_page('edit.php?post_type=nv_application',__('Data Retention','nvconsult-core'),__('Data Retention','nvconsult-core'),'manage_options','nvconsult-retention',[self::class,'render']);}
 public static function render():void{$months=max(1,absint(get_option('nvconsult_retention_months',24)));$cutoff=gmdate('Y-m-d',strtotime('-'.$months.' months'));$ids=get_posts(['post_type'=>'nv_application','post_status'=>'private','numberposts'=>100,'fields'=>'ids','date_query'=>[['before'=>$cutoff,'column'=>'post_modified_gmt']],'meta_query'=>[['key'=>'_nvconsult_status','value'=>['rejected','closed'],'compare'=>'IN']]]);echo'<div class="wrap"><h1>'.esc_html__('Data Retention Review','nvconsult-core').'</h1><form method="post" action="options.php">';settings_fields('nvconsult_retention');echo'<p><label><strong>'.esc_html__('Review closed/rejected cases older than','nvconsult-core').'</strong> <input type="number" min="1" max="120" name="nvconsult_retention_months" value="'.esc_attr((string)$months).'"> '.esc_html__('months','nvconsult-core').'</label> ';submit_button(__('Save','nvconsult-core'),'secondary','submit',false);echo'</p></form><p>'.esc_html(sprintf(__('Current review cutoff: %s. This screen does not automatically delete legal or contractual records.','nvconsult-core'),$cutoff)).'</p><h2>'.esc_html(sprintf(__('Cases requiring retention review (%d shown)','nvconsult-core'),count($ids))).'</h2><ul>';foreach($ids as$id)echo'<li><a href="'.esc_url(get_edit_post_link($id)).'">'.esc_html(sprintf(__('Application #%d','nvconsult-core'),$id)).'</a></li>';if(!$ids)echo'<li>'.esc_html__('No cases currently match the review rule.','nvconsult-core').'</li>';echo'</ul></div>';}
}
